let reviewPracticePlan=null;
const reviewPracticeJobs=new Set();
function reviewPracticeLightStatus(l){const e=S.events.find(e=>e.id===l.eventId),r=e?.practiceReceipts?.at(-1);return r?`${r.visibility==='public'?'服务已公开':'服务私人保存'} · ${r.lightUp?'本人自证':'草稿'}`:l.public?'分享意愿待提交':'本人档案中，未提交实践服务'}
function reviewPracticeShareLabel(l){return S.events.find(e=>e.id===l.eventId)?.practiceReceipts?.at(-1)?.visibility==='public'?'撤回公开':'选择公开证据'}
function reviewPracticeFingerprint(e){return JSON.stringify({id:e.id,startedAt:e.startedAt,endedAt:e.endedAt,segments:e.segments,knowledge:e.knowledge,light:S.lights.filter(l=>l.eventId===e.id).map(l=>({id:l.id,confirmed:l.confirmed,result:l.result,evidence:l.evidence,public:l.public}))})}
async function reviewOpenPractice(eventId){
 const context=reviewContext(),ownerId=context.ownerId,e=S.events.find(e=>e.id===eventId);if(!S.user?.reviewService||!e?.knowledge||e.endedAt===null)return;
 try{
  if(!reviewReady||reviewClient.snapshot().ownerId!==ownerId)throw Error('请先连接本人账号。');const fingerprint=reviewPracticeFingerprint(e);if(!save())throw Error('本机保存未完成，请先保留备份。');await reviewFlush();
  const visibleTutorial=e.knowledge.practiceMode==='visible-tutorial'&&!!e.knowledge.targetServiceReference&&!!e.knowledge.serviceReference;
  const independent=e.knowledge.methodId===null&&e.knowledge.version===null&&e.knowledge.methodTitle==='独立尝试';
  const [mapped,archive]=await Promise.all([independent||visibleTutorial?Promise.resolve({bindings:[]}):reviewKnowledgeRequest('/api/review-method-bindings',{context}),reviewKnowledgeRequest('/api/review-practices',{context})]);
  const current=S.events.find(e=>e.id===eventId);if(!reviewContextCurrent(context)||!current||reviewPracticeFingerprint(current)!==fingerprint)throw Error('事件或账号已变化，请重新核对。');
  const k=current.knowledge,bindings=visibleTutorial?[{service:{id:k.serviceReference.id,version:k.serviceReference.version,title:k.methodTitle,authorId:k.serviceReference.authorId,authorName:k.serviceReference.authorName}}]:mapped.bindings.filter(b=>b.source?.ref?.originId===k.nodeId&&b.source.ref.sourceVersion===k.nodeVersion&&b.source.source.id===k.methodId&&b.source.source.number===k.version&&b.source.target.title===k.nodeTitle&&b.source.target.goal===k.nodeGoal&&(!k.serviceReference||(b.service.id===k.serviceReference.id&&b.service.version===k.serviceReference.version)));
  const lights=S.lights.filter(l=>l.eventId===eventId&&l.confirmed&&l.result?.trim()&&l.evidence?.trim());
  const old=archive.current?.find(r=>r.eventId===eventId)||archive.receipts.filter(r=>r.eventId===eventId).at(-1)||null;
  const origin=S.nodes.find(n=>n.id===k.nodeId),privateTarget=(k.nodeOwnership||origin?.ownership)==='personal'&&(k.nodeVisibility||origin?.visibility)==='private';
  reviewPracticePlan={context,ownerId,eventId,fingerprint,independent,visibleTutorial,privateTarget,bindings:clone(bindings),lights:clone(lights),old:old?clone(old):null};reviewShowPractice(reviewPracticePlan);
 }catch(error){if(reviewContextCurrent(context))modal(`<h2>实践服务尚未核对</h2><p>${esc(reviewIsNetworkError(error)?'连接未完成，事件与私人笔记保留。':error.message)}</p><div class="row actions">${btn('重新核对','review-practice-open:'+eventId)}${btn('稍后再做','dialog-close','ghost')}</div>`,'','实践服务状态')}
}
function reviewShowPractice(plan){
 const e=S.events.find(e=>e.id===plan.eventId),k=e.knowledge,old=plan.old?.record;
 modal(`<h2>保存这一次知识实践</h2><p class="small muted">结束计时只生成草稿。私人保存、本人自证和公开分享分别选择。</p><h3 style="margin-top:18px">${esc(k.nodeTitle)}</h3><p class="pre small">${esc(k.nodeGoal)}</p>${old?`<p class="small muted">服务已有记录：${old.visibility==='public'?'公开':'私人'} · ${old.lightUp?'本人已自证':'未确认点亮'}。更新保留旧回执。</p>`:''}${!plan.bindings.length&&!plan.independent?`<p class="error">这次方法还没有匹配的服务版本。原事件保留；请先核对方法引用，不用当前教程替换当时快照。</p><div class="row actions">${k.serviceReference?btn('重试关联服务引用','review-shared-bind:'+e.id):''}${btn('重新核对','review-practice-open:'+e.id)}${btn('稍后再做','dialog-close','ghost')}</div>`:`<form id="review-practice-form" class="stack">${plan.independent?'<p class="small muted">独立尝试，未选择教程，不创建教程引用。</p>':`<label class="field">当时的方法服务版本<select name="binding" aria-label="实践方法服务版本">${plan.bindings.map((b,i)=>`<option value="${i}">${esc(b.service.title)} · ${esc(b.service.authorName)} · ${esc(b.service.version.slice(0,8))}</option>`).join('')}</select></label>`}<label class="field">保存范围<select name="visibility" aria-label="实践服务保存范围"><option value="private">私人保存到本人账号</option><option value="public">公开这次自证实践</option></select></label><label class="check-row"><input type="checkbox" name="useLight" ${plan.lights.length?'':'disabled'}>保存本人已确认的 L1 自证</label>${plan.lights.length?`<label class="field">本次自证<select name="light" aria-label="本次实践自证">${plan.lights.map(l=>`<option value="${esc(l.id)}">${esc(l.result)}</option>`).join('')}</select></label><details class="saved-notes"><summary>审阅将保存的结果与证据</summary>${plan.lights.map(l=>`<p class="pre small">${esc(l.result)}<br>${esc(l.evidence)}</p>`).join('')}</details>`:'<p class="small muted">尚未确认本次点亮，可以先保存私人草稿。</p>'}<section id="review-practice-public" hidden><p class="small muted">公开内容包括：${plan.independent?'当时目标与起步建议':'当时目标、教程和资料快照'}、上述结果与证据、累计用时及活动段数量。单次笔记、草稿、内部附注和精确起止时间保留在私人档案。</p><label class="check-row"><input type="checkbox" name="publicConsent">我确认公开这次实践与自证证据</label>${old?.images?.length?`<label class="check-row"><input type="checkbox" name="imagesConsent">同时公开原服务记录的 ${old.images.length} 项图片</label>`:''}</section>${old?'<label class="check-row"><input type="checkbox" name="updateConsent" required>我确认用上述选择更新现有服务记录</label>':''}<p id="review-practice-error" class="error" role="alert"></p><button class="primary">确认保存这次实践</button></form><div class="row actions">${btn('重新核对服务记录','review-practice-open:'+e.id,'ghost')}${btn('暂不保存','dialog-close','ghost')}</div>`}`,'','保存知识实践');
 const f=document.getElementById('review-practice-form');if(!f)return;
 const visibility=f.elements.namedItem('visibility'),light=f.elements.namedItem('useLight'),consent=f.elements.namedItem('publicConsent');light.checked=!!old?.lightUp&&plan.lights.length>0;
 if(plan.privateTarget){visibility.querySelector('[value="public"]').disabled=true;const info=document.createElement('p');info.className='small muted';info.textContent='这是服务中的私人目标，实践仅对本人保存；目标分享需另行核对。';f.prepend(info)}
 const update=()=>{const pub=visibility.value==='public';document.getElementById('review-practice-public').hidden=!pub;consent.required=pub;light.required=pub;const images=f.elements.namedItem('imagesConsent');if(images)images.required=pub};visibility.addEventListener('change',update);update();
 f.addEventListener('submit',ev=>{ev.preventDefault();if(f.reportValidity())reviewCommitPractice(plan,f)});
}
async function reviewCommitPractice(plan,form){
 const key=JSON.stringify([plan.ownerId,plan.context.generation,plan.eventId]);if(reviewPracticeJobs.has(key))return;reviewPracticeJobs.add(key);const button=form.querySelector('button');button.disabled=true;
 try{
  const e=S.events.find(e=>e.id===plan.eventId);if(!reviewContextCurrent(plan.context)||!e||reviewPracticeFingerprint(e)!==plan.fingerprint)throw Error('事件或自证已经变化，请重新核对，原内容保留。');
  const data=new FormData(form),binding=plan.bindings[Number(data.get('binding'))],visibility=data.get('visibility'),light=data.has('useLight')?S.lights.find(l=>l.id===data.get('light')&&l.eventId===e.id&&l.confirmed):null;
  if(!plan.independent&&!binding||!['private','public'].includes(visibility)||data.has('useLight')&&!light)throw Error('请选择已核对的当时版本与本次自证。');
  if(visibility==='public'){if(!light||!data.has('publicConsent'))throw Error('公开需要本人自证和单独的分享确认。');light.public=true;plan.fingerprint=reviewPracticeFingerprint(e)}
  if(plan.old&&!data.has('updateConsent'))throw Error('请先确认更新现有记录。');if(!save())throw Error('本机保存未完成，原事件保留。');await reviewFlush();
  if(!reviewContextCurrent(plan.context)||reviewPracticeFingerprint(e)!==plan.fingerprint)throw Error('提交期间内容发生变化，请重新核对。');
  const result=await reviewKnowledgeRequest('/api/review-practices',{context:plan.context,body:{eventId:e.id,tutorialId:plan.independent?null:binding.service.id,tutorialVersion:plan.independent?null:binding.service.version,...(plan.independent?{practiceMode:'independent'}:plan.visibleTutorial?{practiceMode:'visible-tutorial'}:{}),visibility,...(light?{lightId:light.id}:{}),...(data.has('imagesConsent')?{shareExistingImages:true}:{})},headers:{'If-Match':reviewClient.snapshot().revision,...(plan.old?{'If-Practice-Match':plan.old.recordRevision}:{})}});
  if(!reviewContextCurrent(plan.context))return;if(result.record?.eventId!==e.id||result.record.authorId!==plan.ownerId||result.record.visibility!==visibility||result.record.tutorialVersion!==(plan.independent?null:binding.service.version)||(plan.independent&&result.record.practiceMode!=='independent')||(plan.visibleTutorial&&result.record.practiceMode!=='visible-tutorial'))throw Error('服务回执不一致，请重新核对。');
  const current=S.events.find(x=>x.id===e.id);if(current){if(visibility==='private'){const chosenLight=light||S.lights.find(l=>l.eventId===e.id);if(chosenLight)chosenLight.public=false}if(!Array.isArray(current.practiceReceipts))current.practiceReceipts=[];if(!current.practiceReceipts.some(r=>r.revision===result.recordRevision))current.practiceReceipts.push({id:result.record.id,revision:result.recordRevision,visibility:result.record.visibility,lightUp:result.record.lightUp,version:result.record.tutorialVersion,at:Date.now()});save()}
  if(document.getElementById('review-practice-form')===form)closeModal();render(false);toast(visibility==='public'?'知识服务已确认公开这次自证实践。':light?'知识服务已私人保存这次本人自证。':'知识服务已私人保存草稿，未自动确认点亮。');
 }catch(error){if(reviewContextCurrent(plan.context)&&document.getElementById('review-practice-form')===form)document.getElementById('review-practice-error').textContent=reviewIsNetworkError(error)?'连接未完成，原事件与选择保留，可重新核对。':error.message}
 finally{reviewPracticeJobs.delete(key);button.disabled=false}
}
